insert into public.public_profile select * from jsonb_populate_record(null::public.public_profile,'{"id":1,"name":"Maicon Santos","full_name":"Maicon Santos Silva","role":"Conteúdo, design & desenvolvimento","photo_media_id":null,"bio":"Sou profissional especializado em criação e otimização de conteúdo para e-commerce, com experiência prática na produção de materiais visuais, comerciais e técnicos para páginas de produtos.\n\nMinha atuação combina design, inteligência artificial, SEO, organização de informações e desenvolvimento web, buscando soluções que valorizem os produtos e melhorem a experiência de compra.\n\nTambém desenvolvo ferramentas de automação voltadas à produção de conteúdo, unindo tecnologia e criatividade para otimizar processos e entregas.\n\nEstou disponível para projetos pontuais, demandas recorrentes e parcerias com agências e operações de e-commerce.","contacts":[{"label":"E-mail","url":"mailto:maiconsantossilvah@gmail.com"},{"label":"WhatsApp","url":"https://wa.me/qr/R6ER3ERGXMGQC1"},{"label":"LinkedIn","url":"https://www.linkedin.com/in/maicon-santos-silva-3ba402346"},{"label":"GitHub","url":"https://github.com/maiconsantossilvah-dot"}]}'::jsonb);
